package com.budgetowl.common.schedule;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.temporal.ChronoUnit;
import java.time.temporal.TemporalAdjusters;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * When something recurs, and which dates that means in a given month.
 *
 * <p><b>A pure function of its own fields and the month asked about.</b> It reads no clock, no
 * database and no configuration, which is what lets occurrences be projected on read instead of
 * generated by a job (ADR-0032) — and what makes an instance that was switched off for a month
 * answer correctly the moment it comes back.
 *
 * <p>Each kind carries exactly the parameters it needs. The database says the same thing in {@code
 * ck_bills_schedule_parameters}, because a {@code MONTHLY} bill with a weekday and no day of month
 * projects nothing, silently, and looks like a bill nobody set up.
 *
 * @param dayOfMonth 1–31 for {@code MONTHLY} and {@code YEARLY}
 * @param month 1–12 for {@code YEARLY}
 * @param dayOfWeek for {@code WEEKLY} and {@code FORTNIGHTLY}
 * @param anchorDate for {@code FORTNIGHTLY}: the date the every-other-week count starts from.
 *     Without it, "every other Wednesday" names two different sets of Wednesdays and nothing says
 *     which
 */
public record Recurrence(
        ScheduleKind kind,
        Integer dayOfMonth,
        Integer month,
        DayOfWeek dayOfWeek,
        LocalDate anchorDate) {

    public Recurrence {
        Objects.requireNonNull(kind, "kind");
    }

    /** One date a month, clamped to the month's last day — the 31st of February is the 28th. */
    public static Recurrence monthly(int dayOfMonth) {
        requireDayOfMonth(dayOfMonth);
        return new Recurrence(ScheduleKind.MONTHLY, dayOfMonth, null, null, null);
    }

    public static Recurrence yearly(int month, int dayOfMonth) {
        requireDayOfMonth(dayOfMonth);
        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("a month must be 1–12");
        }
        return new Recurrence(ScheduleKind.YEARLY, dayOfMonth, month, null, null);
    }

    public static Recurrence weekly(DayOfWeek dayOfWeek) {
        return new Recurrence(
                ScheduleKind.WEEKLY, null, null, Objects.requireNonNull(dayOfWeek), null);
    }

    public static Recurrence fortnightly(DayOfWeek dayOfWeek, LocalDate anchorDate) {
        return new Recurrence(
                ScheduleKind.FORTNIGHTLY,
                null,
                null,
                Objects.requireNonNull(dayOfWeek, "dayOfWeek"),
                Objects.requireNonNull(anchorDate, "anchorDate"));
    }

    public static Recurrence irregular() {
        return new Recurrence(ScheduleKind.IRREGULAR, null, null, null, null);
    }

    /**
     * The dates this falls on in {@code period}, in order.
     *
     * <p>Empty for {@link ScheduleKind#IRREGULAR}, and empty for a {@code YEARLY} recurrence in any
     * month but its own. Never null, and never depends on today.
     */
    public List<LocalDate> datesIn(YearMonth period) {
        Objects.requireNonNull(period, "period");
        return switch (kind) {
            case IRREGULAR -> List.of();
            // Clamped, so a bill due on the 31st falls on the 30th of April and the 28th of
            // February — and on the 29th in a leap year, because `lengthOfMonth` knows.
            case MONTHLY -> List.of(period.atDay(Math.min(dayOfMonth, period.lengthOfMonth())));
            case YEARLY ->
                    period.getMonthValue() == month
                            ? List.of(period.atDay(Math.min(dayOfMonth, period.lengthOfMonth())))
                            : List.of();
            case WEEKLY -> weekdaysIn(period);
            case FORTNIGHTLY -> everyOtherWeekdayIn(period);
        };
    }

    private List<LocalDate> weekdaysIn(YearMonth period) {
        List<LocalDate> dates = new ArrayList<>(5);
        LocalDate end = period.atEndOfMonth();
        for (LocalDate date = firstMatchingWeekday(period); !date.isAfter(end); ) {
            dates.add(date);
            // Stepped like this rather than in the for-header: `plusWeeks(1)` past the end of the
            // supported calendar throws, and a projection that throws is a 500 with a stack trace
            // on a request anybody can make. The guard costs nothing and the loop cannot overflow.
            if (ChronoUnit.DAYS.between(date, end) < 7) {
                break;
            }
            date = date.plusWeeks(1);
        }
        return dates;
    }

    /**
     * Every other matching weekday, in step with the anchor.
     *
     * <p>Which Wednesdays are "the right ones" is decided by whole weeks between the date and the
     * anchor, not by counting from the start of the month: counting per month would drift every
     * time a month contained five of them, and a fortnightly bill would slowly change weeks.
     */
    private List<LocalDate> everyOtherWeekdayIn(YearMonth period) {
        List<LocalDate> dates = new ArrayList<>(3);
        LocalDate end = period.atEndOfMonth();
        for (LocalDate date = firstMatchingWeekday(period); !date.isAfter(end); ) {
            long weeks = ChronoUnit.WEEKS.between(alignedAnchor(), date);
            // Math.floorMod, not %, so the step is right for dates before the anchor too — a
            // household can set a bill up with an anchor in the future, and the past still works.
            if (Math.floorMod(weeks, 2) == 0) {
                dates.add(date);
            }
            // Bounded for the reason weekdaysIn is.
            if (ChronoUnit.DAYS.between(date, end) < 7) {
                break;
            }
            date = date.plusWeeks(1);
        }
        return dates;
    }

    /** The anchor moved to its own week's matching weekday, so the comparison is like for like. */
    private LocalDate alignedAnchor() {
        return anchorDate.with(TemporalAdjusters.previousOrSame(dayOfWeek));
    }

    private LocalDate firstMatchingWeekday(YearMonth period) {
        return period.atDay(1).with(TemporalAdjusters.nextOrSame(dayOfWeek));
    }

    private static void requireDayOfMonth(int dayOfMonth) {
        if (dayOfMonth < 1 || dayOfMonth > 31) {
            throw new IllegalArgumentException("a day of the month must be 1–31");
        }
    }
}
